/work/implementation/public/styles.css.content:
:root {
  --night: #172526;
  --night-soft: #233839;
  --cream: #f4f0e7;
  --paper: #fffdf8;
  --ink: #263332;
  --muted: #6e7874;
  --line: #ddd8cc;
  --moss: #52735e;
  --moss-dark: #3f604c;
  --moss-pale: #e3ebe3;
  --ochre: #b67531;
  --ochre-pale: #f6ead8;
  --danger: #a3483f;
  --shadow: 0 18px 55px rgba(31, 42, 39, .14);
}

* { box-sizing: border-box; }
html { min-width: 320px; background: var(--cream); }
body { margin: 0; min-height: 100vh; color: var(--ink); background: var(--cream); font-family: "Avenir Next", Avenir, "Segoe UI", sans-serif; }
button, input, textarea { font: inherit; }
button { cursor: pointer; }
button:focus-visible, input:focus-visible, textarea:focus-visible, a:focus-visible { outline: 3px solid rgba(182,117,49,.35); outline-offset: 2px; }

.app-shell { display: grid; grid-template-columns: 248px minmax(0, 1fr); min-height: 100vh; }
.sidebar { position: sticky; top: 0; height: 100vh; display: flex; flex-direction: column; padding: 32px 22px 26px; color: #e9ede8; background: var(--night); }
.brand { display: flex; align-items: center; gap: 12px; margin: 0 8px 50px; color: white; text-decoration: none; font-family: Georgia, serif; font-size: 26px; letter-spacing: .02em; }
.brand svg { width: 34px; height: 34px; fill: none; stroke: #d6b978; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
nav { display: grid; gap: 8px; }
.nav-button { display: flex; align-items: center; gap: 13px; width: 100%; padding: 12px 13px; border: 0; border-radius: 10px; color: #b9c4bf; background: transparent; text-align: left; transition: .16s ease; }
.nav-button:hover { color: white; background: rgba(255,255,255,.06); }
.nav-button.active { color: white; background: var(--night-soft); box-shadow: inset 3px 0 #d6b978; }
