.eyebrow { margin: 0 0 8px; color: var(--ochre); font-size: 11px; font-weight: 800; letter-spacing: .17em; }
h1, h2 { font-family: Georgia, serif; font-weight: 500; }
h1 { margin: 0; color: var(--night); font-size: clamp(32px, 5vw, 44px); line-height: 1.05; }
.view-count { margin: 9px 0 0; color: var(--muted); font-size: 14px; }
.add-button, .primary-button { display: inline-flex; align-items: center; justify-content: center; gap: 9px; border: 0; border-radius: 10px; color: white; background: var(--moss-dark); font-weight: 700; box-shadow: 0 6px 18px rgba(63,96,76,.2); }
