.search-region { display: flex; align-items: center; gap: 10px; margin-top: 34px; padding: 0 15px; border: 1px solid var(--line); border-radius: 12px; background: var(--paper); box-shadow: 0 4px 16px rgba(40,48,44,.04); }
.search-region > svg { flex: 0 0 auto; width: 21px; height: 21px; fill: none; stroke: #77817c; stroke-width: 1.8; stroke-linecap: round; }
.search-region input { width: 100%; padding: 14px 0; border: 0; outline: 0; color: var(--ink); background: transparent; }
.search-region input::placeholder { color: #969d99; }
.clear-search { border: 0; color: var(--moss-dark); background: transparent; font-size: 13px; font-weight: 700; }

.notice { margin-top: 18px; padding: 12px 15px; border: 1px solid #e7d2aa; border-radius: 10px; color: #75501e; background: #fbf0dd; font-size: 13px; }
