.bookmark-card:hover { transform: translateY(-1px); box-shadow: 0 9px 28px rgba(38,51,50,.08); }
.site-mark { display: grid; place-items: center; width: 52px; height: 52px; border-radius: 12px; color: #f7f3e9; background: var(--night-soft); font-family: Georgia, serif; font-size: 23px; text-transform: uppercase; }
.bookmark-title { display: inline; color: var(--night); font-family: Georgia, serif; font-size: 19px; font-weight: 600; line-height: 1.3; text-decoration: none; }
.bookmark-title:hover { color: var(--moss-dark); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
