.action-menu { position: absolute; z-index: 5; top: 43px; right: 0; width: 154px; padding: 6px; border: 1px solid var(--line); border-radius: 10px; background: white; box-shadow: var(--shadow); }
.action-menu button { width: 100%; padding: 9px 10px; border: 0; border-radius: 7px; color: var(--ink); background: transparent; text-align: left; font-size: 13px; }
.action-menu button:hover { background: var(--moss-pale); }
.status-row { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-top: 12px; }
.needs-details { padding: 5px 9px; border-radius: 999px; color: #7a531d; background: var(--ochre-pale); font-size: 11px; font-weight: 800; }
.retry-button { padding: 0; border: 0; color: var(--moss-dark); background: transparent; font-size: 12px; font-weight: 800; }
.archived-badge { padding: 7px 10px; border-radius: 999px; color: #5f6964; background: #ecebe6; font-size: 11px; font-weight: 800; }

.empty-state, .loading-state { display: grid; place-items: center; min-height: 380px; padding: 55px 20px; text-align: center; }
.empty-icon { display: grid; place-items: center; width: 76px; height: 76px; margin: 0 auto 20px; border-radius: 50%; color: var(--moss-dark); background: var(--moss-pale); }
.empty-icon svg { width: 35px; height: 35px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.empty-state h2 { margin: 0 0 9px; color: var(--night); font-size: 24px; }
.empty-state p { max-width: 430px; margin: 0 auto 20px; color: var(--muted); line-height: 1.55; }
.loading-state { color: var(--muted); }
.spinner { width: 28px; height: 28px; border: 3px solid #d9dfda; border-top-color: var(--moss); border-radius: 50%; animation: spin .75s linear infinite; }
.spinner.small { width: 16px; height: 16px; border-width: 2px; }
