.dialog-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }
.dialog h2 { margin: 0; color: var(--night); font-size: 28px; }
.dialog-copy { margin: 12px 0 23px; color: var(--muted); font-size: 14px; line-height: 1.5; }
.dialog label { display: block; margin: 17px 0 7px; font-size: 13px; font-weight: 800; }
.dialog input, .dialog textarea { width: 100%; padding: 12px 13px; border: 1px solid #c8cec9; border-radius: 9px; color: var(--ink); background: white; outline: none; }
.dialog textarea { resize: vertical; }
.dialog input.invalid { border-color: var(--danger); box-shadow: 0 0 0 3px rgba(163,72,63,.1); }
.field-error { margin: 7px 0 0; color: var(--danger); font-size: 12px; }
.dialog-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 25px; }
.primary-button, .secondary-button { min-height: 40px; padding: 10px 16px; border-radius: 9px; }
.secondary-button { border: 1px solid #d2d5cf; color: #58625d; background: white; font-weight: 700; }
.primary-button:disabled { opacity: .55; cursor: wait; }
.close-dialog { flex: 0 0 auto; border: 0; background: transparent; font-size: 25px; }
.working { display: flex; align-items: center; justify-content: flex-end; gap: 8px; margin-top: 13px; color: var(--moss-dark); font-size: 12px; }
.toast { position: fixed; z-index: 20; right: 26px; bottom: 24px; max-width: min(380px, calc(100% - 36px)); padding: 13px 16px; border-radius: 10px; color: white; background: var(--night-soft); box-shadow: var(--shadow); font-size: 13px; }

@media (max-width: 800px) {
  .app-shell { grid-template-columns: 1fr; }
  .sidebar { position: static; width: 100%; height: auto; padding: 18px; }
  .brand { margin: 0 0 18px; }
  nav { grid-template-columns: repeat(3, 1fr); }
  .nav-button { justify-content: center; padding: 10px 7px; }
  .nav-button.active { box-shadow: inset 0 -3px #d6b978; }
  .sidebar-note { display: none; }
  .main { padding: 30px 20px 60px; }
}

@media (max-width: 600px) {
  .topbar { align-items: flex-start; }
  .add-button { width: 44px; height: 44px; padding: 0; }
  .add-button svg { width: 21px; height: 21px; }
  .add-button { font-size: 0; }
  .bookmark-card { grid-template-columns: 43px minmax(0, 1fr); padding: 17px; }
  .site-mark { width: 43px; height: 43px; }
  .card-actions { grid-column: 2; justify-content: flex-start; }
  nav { gap: 3px; }
  .nav-button { flex-direction: column; gap: 4px; font-size: 11px; }
}

